/* Local OMR companion integration. No provider key is accepted by the browser. */
(function(){
const defaultService=location.hostname==='localhost'||location.hostname==='127.0.0.1'?location.origin:'http://127.0.0.1:8765';
function service(){return localStorage.getItem('fret-recognition-url')||defaultService}
async function api(path,options={}){let response;try{response=await fetch(service()+path,{...options,signal:options.signal||AbortSignal.timeout(15000)})}catch(e){if(e.name==='AbortError')throw e;throw Error('无法连接识谱服务。请先在 Mac 启动服务，再从 http://127.0.0.1:8765 打开应用；也可在设置中修改服务地址。')}let data;try{data=await response.json()}catch{throw Error('服务未返回有效 JSON，请检查地址')}if(!response.ok)throw Error(typeof data.detail==='string'?data.detail:'识谱服务请求失败');return data}
window.recognitionSettings=function(){modal('识谱服务设置','Audiveris 本地运行 · VLM 使用 OpenAI 兼容协议',`<div class="field"><label for="omr-url">识谱服务地址</label><input id="omr-url" value="${esc(service())}" placeholder="http://127.0.0.1:8765"></div><p class="help">建议从本地服务打开应用。在线预览访问 localhost 时，浏览器可能要求本地网络权限。<br>VLM 的 Base URL、模型和 Key 在服务端 .env.local 中配置，网页不保存 API Key。</p><p class="help"><a class="btn small" href="downloads/fret-source.zip" download>下载 Mac 本地服务与源码</a></p><pre class="config-example">VLM_BASE_URL=https://api.openai.com/v1\nVLM_MODEL=\nVLM_API_KEY=</pre><div class="service-status" id="omr-health">尚未检测</div><div class="modal-actions"><button class="btn" id="omr-test">检测连接</button><button class="btn primary" id="omr-save">保存地址</button></div>`);function save(){let u;try{u=new URL($('#omr-url').value.trim());if(!['http:','https:'].includes(u.protocol)||u.username||u.password||u.search||u.hash)throw Error();if(u.protocol==='http:'&&!['localhost','127.0.0.1','[::1]'].includes(u.hostname))throw Error()}catch{throw Error('请使用 HTTPS 地址，或 http://127.0.0.1:8765 本地地址')}localStorage.setItem('fret-recognition-url',u.origin)}$('#omr-save').onclick=()=>{try{save();closeModal();toast('服务地址已保存')}catch(e){toast(e.message)}};$('#omr-test').onclick=async()=>{try{save();$('#omr-health').textContent='正在检测…';let h=await api('/api/health');$('#omr-health').textContent=`服务已连接 · Audiveris ${h.audiveris.configured?'就绪':'未配置'} · VLM ${h.vlm.configured?'已配置':'占位接口，未配置'}`}catch(e){$('#omr-health').textContent=e.message}}};
window.openRecognition=function(){modal('识别曲谱，跟着原谱练习。','上传 PDF / 图片自动识谱，或直接导入 MusicXML。',`<div class="dropzone" tabindex="0" role="button" aria-label="选择识谱文件">${icon('upload',30)}<h3>拖入乐谱，或点击选择</h3><p>PDF、PNG、JPG、WebP、MusicXML、MXL · 最大 20 MB</p></div><input id="recognition-file" type="file" accept=".pdf,.png,.jpg,.jpeg,.webp,.xml,.musicxml,.mxl" hidden><div class="import-options"><button class="btn small" id="omr-paste">⌘ V 粘贴截图</button><button class="btn small" id="omr-settings">${icon('settings',14)} 服务设置</button></div><div id="omr-selected" class="help"></div><div class="field"><label for="omr-engine">识谱方式</label><select id="omr-engine"><option value="audiveris">Audiveris · 标准五线谱</option><option value="vlm">VLM · 六线谱 / 混合谱（需配置）</option></select></div><p class="help">保留音符、休止、拍号、时值、附点、连音与速度变化。MusicXML 直接解析，无需模型。Audiveris 的结果必须校对；缺少的节奏和 BPM 不会自动补猜。</p><div class="service-status" id="omr-status" role="status">识谱完成后可选择声部、校正时值，并对照原谱试听。<br>首次使用请 <a href="downloads/fret-source.zip" download style="text-decoration:underline">下载并启动本地识谱服务</a>，安装步骤见包内 README。</div><div class="modal-actions"><button class="btn" id="omr-manual">仅保存原谱</button><button class="btn primary" id="omr-start">${icon('search',15)} 开始识谱</button></div>`);let file=null,alive=true,controller=new AbortController();const setFile=f=>{if(!f)return;if(f.size>20*1024*1024){toast('文件超过 20 MB');return}file=f;$('#omr-selected').textContent=`已选择：${f.name} · ${(f.size/1024).toFixed(0)} KB`;if(/\.(xml|musicxml|mxl)$/i.test(f.name))$('#omr-engine').disabled=true;else $('#omr-engine').disabled=false};let zone=$('.dropzone');zone.onclick=()=>$('#recognition-file').click();zone.onkeydown=e=>{if(e.key==='Enter')$('#recognition-file').click()};zone.ondragover=e=>{e.preventDefault();zone.classList.add('over')};zone.ondragleave=()=>zone.classList.remove('over');zone.ondrop=e=>{e.preventDefault();zone.classList.remove('over');setFile(e.dataTransfer.files[0])};$('#recognition-file').onchange=e=>setFile(e.target.files[0]);const paste=e=>{let f=Array.from(e.clipboardData?.files||[])[0];if(f){e.preventDefault();setFile(new File([f],`截图-${Date.now()}.png`,{type:f.type}))}};document.addEventListener('paste',paste);cleanup=()=>{alive=false;controller.abort();document.removeEventListener('paste',paste)};$('#omr-paste').onclick=()=>toast('按 ⌃⇧⌘4 截图到剪贴板，再在这里按 ⌘V');$('#omr-settings').onclick=window.recognitionSettings;$('#omr-manual').onclick=manualImportModal;$('#omr-start').onclick=async()=>{if(!file){toast('请先选择乐谱');return}const button=$('#omr-start');button.disabled=true;button.textContent='识谱中…';try{let form=new FormData();form.append('file',file);form.append('engine',$('#omr-engine').value);let job=await api('/api/recognitions',{method:'POST',body:form,signal:controller.signal});let deadline=Date.now()+420000;while(alive){let result=await api('/api/recognitions/'+job.id,{signal:controller.signal});if(!alive)return;$('#omr-status').textContent=result.stage;if(result.status==='failed')throw Error(result.error);if(result.status==='completed'){window.reviewRecognition(result.score,file);return}if(Date.now()>deadline)throw Error('等待识谱超时，请检查本地服务。任务可能仍在运行。');await new Promise(r=>setTimeout(r,1000))}}catch(e){if(alive){$('#omr-status').textContent=e.message;button.disabled=false;button.innerHTML=`${icon('refresh',15)} 重试识谱`}}}};
function makePart(score,i,bpm,meter){let p=structuredClone(score.parts[i]);if(bpm&&!p.tempos.some(t=>t.beat===0))p.tempos.unshift({beat:0,bpm});if(meter){let m=/^(\d+)\s*\/\s*(\d+)$/.exec(meter);if(!m||+m[1]<1||+m[2]<1)throw Error('拍号格式例如 4/4 或 6/8');for(let measure of p.measures)if(!measure.numerator){measure.numerator=+m[1];measure.denominator=+m[2]}}return p}
window.reviewRecognition=function(score,file,song=null){let startAfter=false,selected=0,previewTimer=[],previewActive=false,active=true;const draft=structuredClone(score);modal(song?'校对曲谱与节奏':'识谱完成，先听一听。','确认声部、音符与节奏后，再生成游戏时间轴。',`<div class="recognition-summary"><span class="tag green">${esc(score.source)}</span><span>${score.parts.length} 个声部</span><span>时值单位：四分音符 = 1 拍</span></div><div class="input-row"><div class="field"><label for="review-title">曲谱名称</label><input id="review-title" maxlength="80" value="${esc(song?.title||score.title)}"></div><div class="field"><label for="review-part">练习声部</label><select id="review-part">${score.parts.map((p,i)=>`<option value="${i}">${esc(p.name)} · ${p.events.length} 个事件</option>`).join('')}</select></div><div class="field"><label for="review-bpm">缺省起始 BPM（仅原谱缺失时）</label><input id="review-bpm" type="number" min="10" max="400" placeholder="未标速度时必须填写"></div><div class="field"><label for="review-meter">缺省拍号（仅原谱缺失时）</label><input id="review-meter" placeholder="例如 4/4"></div></div><div id="review-warnings" class="recognition-warnings"></div><div class="recognition-toolbar"><button class="btn small" id="review-source">${icon('file',14)} 对照原谱</button><button class="btn small" id="review-preview">${icon('play',14)} 按原谱节奏试听</button><span class="help" id="review-summary"></span></div><div id="review-source-panel"></div><div class="score-table-wrap"><table class="score-table"><thead><tr><th>小节</th><th>音符 / 弦品</th><th>起点（拍）</th><th>时值（拍）</th><th>MIDI 音高</th><th>休止</th></tr></thead><tbody id="review-events"></tbody></table></div><p class="help">可直接修改音符起点、时值与 MIDI 音高（中央 C = 60）；不会自动移动其他音符。附点四分音符 = 1.5，八分三连音 = 1/3。复杂反复与跳转目前按谱面顺序，需核对后使用。</p><label class="review-confirm"><input type="checkbox" id="review-confirm"> 我已对照原谱检查音符、节奏与识别警告，确认此声部可用于练习。</label><div class="modal-actions"><button class="btn" id="review-download">下载结构化乐谱</button>${song?'<button class="btn" id="review-play">开始原谱练习</button>':''}<button class="btn primary" id="review-save">确认并保存曲谱</button></div>`,true);
function stop(){previewTimer.forEach(clearTimeout);previewTimer=[];previewActive=false;if($('#review-preview'))$('#review-preview').innerHTML=`${icon('play',14)} 按原谱节奏试听`}
cleanup=()=>{active=false;stop()};function build(){return makePart(draft,selected,+$('#review-bpm').value,$('#review-meter').value.trim())}function draw(){stop();let p=draft.parts[selected];$('#review-events').innerHTML=p.events.map((e,i)=>`<tr><td>${e.measure}</td><td>${esc(e.label||'音符')} ${e.string!==null&&e.string!==undefined?`<span class="tag">${e.string}弦 ${e.fret}品</span>`:''}</td><td><input type="number" data-event="${i}" data-field="beat" min="0" step="any" value="${e.beat}" aria-label="第 ${i+1} 个事件起点"></td><td><input type="number" data-event="${i}" data-field="duration" min="0.001" step="any" value="${e.duration}" aria-label="第 ${i+1} 个事件时值"></td><td><input type="number" data-event="${i}" data-field="midi" min="0" max="127" step="1" value="${e.midi??''}" aria-label="第 ${i+1} 个事件音高"></td><td><input type="checkbox" data-event="${i}" data-field="rest" ${e.rest?'checked':''} aria-label="第 ${i+1} 个事件休止"></td></tr>`).join('');let warnings=[...draft.warnings,...p.warnings];$('#review-warnings').innerHTML=warnings.map(w=>`<div>• ${esc(w)}</div>`).join('');$('#review-summary').textContent=`${p.measures.length} 小节 · ${p.events.length} 个事件 · ${p.tempos.length} 个速度标记`;$('#review-confirm').checked=false;document.querySelectorAll('[data-event]').forEach(input=>input.onchange=()=>{stop();let e=p.events[+input.dataset.event],field=input.dataset.field;e[field]=field==='rest'?input.checked:input.value===''?null:+input.value;if(field==='midi')e.label=e.midi===null?'未知':midiLabel(e.midi);$('#review-confirm').checked=false})}
$('#review-part').onchange=e=>{selected=+e.target.value;draw()};$('#review-bpm').oninput=()=>{stop();$('#review-confirm').checked=false};$('#review-meter').oninput=()=>{$('#review-confirm').checked=false};draw();
$('#review-preview').onclick=()=>{if(previewActive){stop();return}try{let t=FretTimeline.timeline(build());if(t.duration>1800)throw Error('试听最多 30 分钟，请分段导入');audio();previewActive=true;$('#review-preview').innerHTML=`${icon('pause',14)} 停止试听`;for(let e of t.events.filter(e=>!e.rest))previewTimer.push(setTimeout(()=>{if(active)tone(440*2**((e.midi-69)/12),Math.min(e.length,.9),0,.07)},e.start*1000));previewTimer.push(setTimeout(stop,t.duration*1000+100))}catch(e){toast(e.message)}};
$('#review-source').onclick=async()=>{if($('#review-source-panel').innerHTML){$('#review-source-panel').innerHTML='';return}let original=file;try{if(!original&&song)original=await dbFile(song.id);if(!active)return;if(!original)throw Error('原始文件不可用');let url=URL.createObjectURL(original);blobUrls.push(url);$('#review-source-panel').innerHTML=original.type==='application/pdf'?`<object class="source-view" data="${url}" type="application/pdf"><a href="${url}" target="_blank">打开原始 PDF</a></object>`:original.type.startsWith('image/')?`<img class="source-view" src="${url}" alt="原始乐谱">`:'<p class="help">导入源为 MusicXML，可通过下载按钮保存校对后的结构化数据。</p>'}catch(e){toast(e.message)}};
$('#review-download').onclick=()=>{try{let p=build();let blob=new Blob([JSON.stringify({...draft,parts:[p]},null,2)],{type:'application/json'});let u=URL.createObjectURL(blob);blobUrls.push(u);let a=document.createElement('a');a.href=u;a.download='fret-score.json';a.click()}catch(e){toast(e.message)}};
if(song)$('#review-play').onclick=()=>{startAfter=true;$('#review-save').click()};$('#review-save').onclick=async()=>{try{if(!$('#review-confirm').checked)throw Error('请先完成原谱校对并勾选确认');let title=$('#review-title').value.trim();if(!title)throw Error('请填写曲谱名称');let p=build();let t=FretTimeline.timeline(p);if(t.duration>1800)throw Error('单次练习最多 30 分钟，请分段导入');let id=song?.id||'omr-'+Date.now();if(file)await dbFile(id,file);if(!active)return;let record={...song,id,title,artist:'已校对曲谱',level:'原谱节奏',bpm:t.tempos[0].bpm,chords:[],cover:'paper',imported:true,filename:file?.name||song?.filename,progress:song?.progress||0,score:{...draft,parts:[p]},reviewed:true};if(song)Object.assign(song,record);else state.songs.push(record);persist();closeModal();state.page='library';state.tab='import';render();toast('已保存真实节奏时间轴，可以开始练习');if(startAfter)window.playRecognized(id)}catch(e){startAfter=false;toast(e.message)}};
};
function midiLabel(midi){const names=['C','C♯','D','E♭','E','F','F♯','G','A♭','A','B♭','B'];return names[Math.round(midi)%12]+(Math.floor(midi/12)-1)}
window.playRecognized=function(id){let song=state.songs.find(s=>s.id===id),timeline;try{if(!song.reviewed)throw Error('请先校对曲谱');timeline=FretTimeline.timeline(song.score.parts[0])}catch(e){toast(e.message);return}let groups=timeline.groups,total=groups.length;modal(esc(song.title),'原谱节奏挑战 · 每个音符或同时发声的音组对应一次判定',`<div class="recognition-summary"><span class="tag green">${esc(song.score.source)}</span><span>${timeline.measures[0].numerator}/${timeline.measures[0].denominator}</span><span>${total} 次起音 · ${timeline.duration.toFixed(1)} 秒</span><span>原谱速度变化 ${timeline.tempos.length} 处</span></div><div class="game-panel"><div class="game-hud"><div>得分<strong id="r-score">0</strong></div><div>连击<strong id="r-combo">0</strong></div><div>命中<strong id="r-hits">0 / ${total}</strong></div><div>当前小节<strong id="r-measure">1</strong></div></div><div class="fretboard recognized-fretboard"><div class="hit-zone"></div><div class="hit-line"></div>${Array.from({length:6},(_,i)=>`<div class="string" style="top:${24+i*35}px"></div>`).join('')}<div id="r-notes"></div></div><div class="feedback" id="r-feedback">休止符保留留白，长音按原谱延续</div><div class="game-controls"><button class="btn primary" id="r-start">${icon('play',14)} 开始练习</button><span class="help" id="r-time">0:00 / ${format(timeline.duration)}</span><button class="btn" id="r-hit">${icon('music',14)} 拨弦 / 空格</button><button class="btn small" id="r-audio">引导音：开</button></div><p class="game-hint">键盘判定起音时机；请跟随提示在吉他上弹奏。当前不评分真实吉他音高或持续音长度。</p></div><div class="progress-track" style="margin-top:20px"><i id="r-bar" style="width:0%"></i></div>`,true);let active=true,running=false,elapsed=-2500,started=0,raf,score=0,combo=0,hits=0,finished=false,sound=true,lastAudio=-1;let marks=groups.map(()=>null);function time(){return (running?elapsed+performance.now()-started:elapsed)/1000}function stats(){$('#r-score').textContent=score;$('#r-combo').textContent=combo;$('#r-hits').textContent=`${hits} / ${total}`}function finish(){if(finished)return;finished=true;let final=Math.max(0,Math.min(time(),timeline.duration));running=false;state.history.push({song:id,date:Date.now(),seconds:Math.round(final),accuracy:Math.round(hits/total*100),score});song.progress=Math.max(song.progress||0,Math.round(hits/total*100));persist();modal('听见自己的进步。','原谱节奏练习已完成',`<div class="result"><div class="score">${score}</div><p>命中 ${hits} / ${total} · 准确率 ${Math.round(hits/total*100)}%</p><p class="help">按原谱的时值、休止符和速度变化生成。本次分数仅评价键盘起音节奏。</p></div><div class="modal-actions"><button class="btn" id="r-finish">完成</button><button class="btn primary" id="r-retry">再练一次</button></div>`);$('#r-finish').onclick=()=>{closeModal();render()};$('#r-retry').onclick=()=>window.playRecognized(id)}
function loop(){if(!active)return;let t=time(),html='',width=$('.fretboard').clientWidth,scale=width*.8/3;for(let i=0;i<groups.length;i++){let g=groups[i],delta=g.start-t;if(running&&marks[i]===null&&delta<-.2){marks[i]='miss';combo=0;$('#r-feedback').textContent='MISS · 跟上下一拍';stats()}if(running&&i>lastAudio&&g.start<=t){lastAudio=i;if(sound&&delta>-.15)for(let e of g.notes)tone(440*2**((e.midi-69)/12),Math.min(e.length,1.5),0,.055/Math.sqrt(g.notes.length))}let x=width*.2+delta*scale;if(x+g.length*scale>0&&x<width+30){html+=`<div class="rhythm-note ${marks[i]||''}" style="left:${x}px;width:${Math.max(28,Math.min(500,g.length*scale))}px;top:${g.notes[0].string?Math.min(5,g.notes[0].string-1)*35+9:60}px"><b>${esc(g.notes.map(n=>n.string?`${n.string}弦${n.fret}品`:midiLabel(n.midi)).join(' + '))}</b><small>${g.notes[0].duration.toFixed(3).replace(/0+$/,'').replace(/\.$/,'')} 拍</small></div>`}}
for(let m of timeline.measures){let x=width*.2+(m.start-t)*scale;if(x>0&&x<width)html+=`<div class="measure-line" style="left:${x}px"><span>${m.printedNumber} · ${m.numerator}/${m.denominator}</span></div>`}$('#r-notes').innerHTML=html;let m=timeline.measures.filter(m=>m.start<=t).at(-1);$('#r-measure').textContent=m?.printedNumber||'1';$('#r-time').textContent=`${format(Math.max(0,t))} / ${format(timeline.duration)}`;$('#r-bar').style.width=Math.max(0,Math.min(100,t/timeline.duration*100))+'%';if(running&&t>=timeline.duration+.25){finish();return}raf=requestAnimationFrame(loop)}
function toggle(){if(running){elapsed=time()*1000;running=false;$('#r-start').innerHTML=`${icon('play',14)} 继续练习`}else{audio();started=performance.now();running=true;$('#r-start').innerHTML=`${icon('pause',14)} 暂停`}}
function hit(){if(!running)return;let t=time(),best=-1,delta=Infinity;groups.forEach((g,i)=>{if(marks[i]!==null)return;let d=Math.abs(t-g.start);if(d<delta){delta=d;best=i}});if(delta<=.2){marks[best]='hit';hits++;combo++;score+=delta<.085?100:60;$('#r-feedback').textContent=delta<.085?'PERFECT · 正是此刻！':'GOOD · 保持节奏';stats()}else{combo=0;stats();$('#r-feedback').textContent='留意休止和下一次起音'}}$('#r-start').onclick=toggle;$('#r-hit').onclick=hit;$('#r-audio').onclick=()=>{sound=!sound;$('#r-audio').textContent='引导音：'+(sound?'开':'关')};const key=e=>{if(e.code==='Space'&&!['INPUT','SELECT'].includes(e.target.tagName)){e.preventDefault();if(!e.repeat)running?hit():toggle()}};document.addEventListener('keydown',key);cleanup=()=>{active=false;cancelAnimationFrame(raf);document.removeEventListener('keydown',key)};loop()};
function format(s){return Math.floor(s/60)+':'+String(Math.floor(s%60)).padStart(2,'0')}
})();
